#include <stdio.h> #include <unistd.h> #include <stdlib.h> int main(void) { printf("Real user ID: %d
", getuid()); printf("Effective user ID: %d
", geteuid()); printf("Real group ID: %d
", getgid()); printf("Effective group ID: %d
", getegid()); return 0; }

#include <stdio.h> #include <sys/types.h> #include <unistd.h> int main () { pid_t child_pid; printf("the main program process ID is %d
", (int) getpid()); child_pid = fork(); if (child_pid != 0) { printf("this is the parent process, with id %d
", (int) getpid()); printf("the child's process ID is %d
", (int) child_pid); } else { printf("this is the child process, with id %d
", (int) getpid()); } return 0; }
